// Best score to date on three benchmarks the chapter discusses, from the
// leaderboards it cites (data/benchmark-headroom.ts, generated by
// tools/figure-data/benchmark-headroom.py).
//
// Each series is the running maximum of the listed entries. ARC-AGI-2 and
// ARC-AGI-3 entries sit at the model's release date as ARC Prize lists it, or
// at the benchmark's public launch when the model is older (it could not have
// been scored before). HLE entries sit at the date they were added to Scale's
// leaderboard, which lists only its current entries, so the HLE line starts
// in April 2025 rather than at the January 2025 release. ARC-AGI-3 is drawn
// once per harness: the standard harness keeps only the notes the model
// writes, the provider adapter also keeps the provider's reasoning state.
// Two scores reported under a different protocol with the same benchmark
// name sit apart as hollow diamonds at the date of the leaderboard read: the
// ARC-AGI-2 private set, where only competition entries run, and a
// vendor-reported HLE score with tools.

import { defineFigure, type Lang, type State } from "./types.ts";
import { svg, el, text, g } from "./lib/svg.ts";
import { C, TYPE } from "./lib/theme.ts";
import { linear } from "./lib/scale.ts";
import { axis, axisHeight } from "./lib/axis.ts";
import { placeLabels, drawLabels, lineObstacles, overlaps, textBox, textWidth, wrap, type Box, type LabelRequest } from "./lib/labels.ts";
import { fixed, sig, tpl } from "./lib/format.ts";
import { wrapCjk } from "./lib/kinsoku.ts";
import { HLE, ARC2, ARC3, REFERENCE, SOURCE, type Entry } from "./data/benchmark-headroom.ts";

// ---------------------------------------------------------------- data

type Focus = "hle" | "arc2" | "arc3";
type P = { focus: Focus };
type SeriesKey = "hle" | "arc2" | "arc3std" | "arc3pa";

const dayNum = (iso: string) => {
  const [y, m, d] = iso.split("-").map(Number);
  return Date.UTC(y, m - 1, d) / 86400000;
};
// The leaderboard read the lines run to; the other-protocol diamonds sit here
// too, since they are values as of that read, not results at a release date.
const END = dayNum(SOURCE.arcGenerated);

interface Placed { x: number; score: number; name: string }
interface Series { key: SeriesKey; focus: Focus; color: string; dash?: string; entries: Placed[]; steps: Placed[] }

function placed(entries: readonly Entry[], launch?: string): Placed[] {
  const x0 = launch ? dayNum(launch) : -Infinity;
  return entries.map((e) => ({ x: Math.max(dayNum(e.date), x0), score: e.score, name: e.name })).sort((a, b) => a.x - b.x || b.score - a.score);
}
function steps(ps: Placed[]): Placed[] {
  const out: Placed[] = [];
  for (const p of ps) if (!out.length || p.score > out[out.length - 1].score) out.push(p);
  return out;
}
function series(key: SeriesKey, focus: Focus, color: string, entries: Placed[], dash?: string): Series {
  return { key, focus, color, dash, entries, steps: steps(entries) };
}

const SERIES: Series[] = [
  series("hle", "hle", C.c1, placed(HLE)),
  series("arc2", "arc2", C.c2, placed(ARC2, REFERENCE.arc2Launch)),
  series("arc3std", "arc3", C.c3, placed(ARC3.filter((e) => !e.adapter), REFERENCE.arc3Launch)),
  series("arc3pa", "arc3", C.c3, placed(ARC3.filter((e) => e.adapter), REFERENCE.arc3Launch), "6 3"),
];
const S = Object.fromEntries(SERIES.map((s) => [s.key, s])) as Record<SeriesKey, Series>;
const last = (s: Series) => s.steps[s.steps.length - 1];
const first = (s: Series) => s.steps[0];

// ---------------------------------------------------------------- labels

const MONTHS_EN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const MONTHS_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
function dateOf(x: number, lang: Lang) {
  const d = new Date(x * 86400000);
  return lang === "zh" ? `${d.getUTCFullYear()} 年 ${d.getUTCMonth() + 1} 月 ${d.getUTCDate()} 日` : `${d.getUTCDate()} ${MONTHS_EN[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}
const pctOf = (v: number, key: SeriesKey) => `${fixed(v, key === "hle" || v < 1 ? 2 : 1)}%`;

const labels = {
  en: {
    title: "Benchmark headroom over time",
    hle: "HLE, no tools",
    arc2: "ARC-AGI-2",
    arc3std: "ARC-AGI-3, standard harness",
    arc3pa: "ARC-AGI-3, provider adapter",
    other: "other protocol, same name",
    human: "human result",
    y: "best score to date",
    x: "model release date (ARC) or date listed (HLE)",
    launch2: "ARC-AGI-2 launch",
    launch3: "ARC-AGI-3 launch",
    private: "ARC-AGI-2 private set: {v}",
    tools: "HLE with tools, vendor: {v}",
    humanAvg: "human panel average {v}",
    humanAll: "humans {v}",
    readHle: "HLE on Scale's leaderboard, no tools: the best listed entry scored {s0} when the current list begins on {d0}, and {s1} by {d1}, from {n1}. A vendor-reported score with tools, {st}, comes from a different system under test and does not continue this line.",
    readArc2: "ARC-AGI-2, verified semi-private set: the best entry scored {s0} at launch on {d0} and {s1} by {d1}, from {n1}. It passed the {h} human panel average on {dh}, {mh} months after launch. On the private set, where only competition entries run, the best is {sp}.",
    readArc3: "ARC-AGI-3: the best entry scored {s0} at launch on {d0}. By {d1}, {n1} scored {s1} under the standard harness, and the best entry under the provider adapter scored {s2}. Humans solve {h}.",
    describe: "Best listed score by {date}: HLE without tools {h}, ARC-AGI-2 {a2}, ARC-AGI-3 {a3} with the standard harness and {a3p} with the provider adapter. Every listed entry of {f} is shown.",
  },
  zh: {
    title: "基准可区分空间随时间的变化",
    hle: "HLE，不用工具",
    arc2: "ARC-AGI-2",
    arc3std: "ARC-AGI-3，标准框架",
    arc3pa: "ARC-AGI-3，服务商适配框架",
    other: "同名基准的其他协议",
    human: "人类成绩",
    y: "截至当时的最高分",
    x: "模型发布日期（ARC）或上榜日期（HLE）",
    launch2: "ARC-AGI-2 发布",
    launch3: "ARC-AGI-3 发布",
    private: "ARC-AGI-2 私有题集：{v}",
    tools: "HLE 启用工具，厂商自报：{v}",
    humanAvg: "人类测试组平均 {v}",
    humanAll: "人类 {v}",
    readHle: "Scale 排行榜上的 HLE，不用工具：现有榜单从 {d0}开始，当时最高分为 {s0}；到 {d1}，最高分为 {s1}，来自 {n1}。厂商自报的启用工具分数 {st} 来自另一个受测系统，不是这条曲线的延续。",
    readArc2: "ARC-AGI-2 经验证的半私有题集：{d0}发布时最高分为 {s0}，到 {d1} 为 {s1}，来自 {n1}。最高分在 {dh}超过人类测试组平均的 {h}，距发布 {mh} 个月。私有题集上只有竞赛方案参评，最高为 {sp}。",
    readArc3: "ARC-AGI-3：{d0}发布时最高分为 {s0}。到 {d1}，{n1} 在标准框架下得到 {s1}；服务商适配框架下的最好成绩为 {s2}。人类可以解出 {h}。",
    describe: "截至 {date} 的榜上最高分：HLE 不用工具 {h}，ARC-AGI-2 {a2}，ARC-AGI-3 标准框架 {a3}、服务商适配框架 {a3p}。图中逐条画出了 {f} 的全部条目。",
  },
};

const FOCUS_NAME: Record<Focus, string> = { hle: "HLE", arc2: "ARC-AGI-2", arc3: "ARC-AGI-3" };

function describe(st: State<P>, lang: Lang): string {
  const L = labels[lang];
  return tpl(L.describe, {
    f: FOCUS_NAME[st.p.focus],
    date: dateOf(END, lang), h: pctOf(last(S.hle).score, "hle"), a2: pctOf(last(S.arc2).score, "arc2"),
    a3: pctOf(last(S.arc3std).score, "arc3std"), a3p: pctOf(last(S.arc3pa).score, "arc3pa"),
  });
}

function readout(focus: Focus, lang: Lang): string {
  const L = labels[lang];
  if (focus === "hle") {
    const s = S.hle, a = first(s), b = last(s);
    return tpl(L.readHle, { s0: pctOf(a.score, "hle"), d0: dateOf(a.x, lang), s1: pctOf(b.score, "hle"), d1: dateOf(b.x, lang), n1: b.name, st: pctOf(REFERENCE.hleWithTools.score, "arc2") });
  }
  if (focus === "arc2") {
    const s = S.arc2, a = first(s), b = last(s);
    const cross = s.steps.find((p) => p.score >= REFERENCE.arc2HumanAverage)!;
    return tpl(L.readArc2, {
      s0: pctOf(a.score, "arc2"), d0: dateOf(a.x, lang), s1: pctOf(b.score, "arc2"), d1: dateOf(b.x, lang), n1: b.name,
      h: `${REFERENCE.arc2HumanAverage}%`, dh: dateOf(cross.x, lang), mh: sig((cross.x - dayNum(REFERENCE.arc2Launch)) / 30.44, 2),
      sp: pctOf(REFERENCE.arc2Private.score, "arc2"),
    });
  }
  const s = S.arc3std, a = first(s), b = last(s);
  return tpl(L.readArc3, { s0: pctOf(a.score, "arc3std"), d0: dateOf(a.x, lang), d1: dateOf(b.x, lang), n1: b.name, s1: pctOf(b.score, "arc3std"), s2: pctOf(last(S.arc3pa).score, "arc3pa"), h: `${REFERENCE.arc3Human}%` });
}

// ---------------------------------------------------------------- render

function diamond(cx: number, cy: number, r: number): string {
  return `M${cx},${cy - r}L${cx + r},${cy}L${cx},${cy + r}L${cx - r},${cy}Z`;
}

function render(st: State<P>, lang: Lang): string {
  const L = labels[lang];
  const w = st.w;
  const narrow = w < 480;
  const fs = TYPE.body;
  const focus = st.p.focus;
  const parts: string[] = [];

  // ---- legend
  let y = 0;
  {
    type Item = { label: string; draw: (x: number, yy: number) => string };
    const line = (s: Series): Item => ({ label: L[s.key], draw: (x, yy) => el("line", { x1: x, x2: x + 20, y1: yy - 4, y2: yy - 4, stroke: s.color, "stroke-width": 2.5, "stroke-dasharray": s.dash }) });
    const items: Item[] = [
      ...SERIES.map(line),
      { label: L.other, draw: (x, yy) => el("path", { d: diamond(x + 10, yy - 4, 5), fill: C.paper, stroke: C.ink2, "stroke-width": 1.5 }) },
      { label: L.human, draw: (x, yy) => el("line", { x1: x, x2: x + 20, y1: yy - 4, y2: yy - 4, stroke: C.ink2, "stroke-width": 1.5, "stroke-dasharray": "1 3", "stroke-linecap": "round" }) },
    ];
    let cx = 0, row = 0;
    for (const it of items) {
      const iw = 26 + textWidth(it.label, fs);
      if (cx > 0 && cx + iw > w) { cx = 0; row++; }
      const yy = 14 + row * 20;
      parts.push(it.draw(cx, yy), text(cx + 26, yy, it.label, { "font-size": fs, class: "fig-t-muted" }));
      cx += iw + 16;
    }
    y = 14 + row * 20 + 14;
  }

  // ---- plot
  const left = narrow ? 40 : 46, right = narrow ? 8 : 14;
  const top = y + 24;
  const h = narrow ? 250 : 290;
  const x0 = dayNum("2025-03-01"), x1 = dayNum("2026-10-15");
  const xs = linear([x0, x1], [left + 4, w - right]);
  const ys = linear([0, 100], [top + h, top]);
  const ticks: number[] = [];
  for (let yr = 2025; yr <= 2026; yr++) for (let mo = 0; mo < 12; mo += narrow ? 6 : 3) {
    const t = Date.UTC(yr, mo, 1) / 86400000;
    if (t >= x0 && t <= x1) ticks.push(t);
  }
  const fmtX = (v: number) => {
    const d = new Date(v * 86400000);
    if (lang === "zh") return d.getUTCMonth() === 0 ? `${d.getUTCFullYear()} 年` : `${d.getUTCMonth() + 1} 月`;
    return d.getUTCMonth() === 0 ? String(d.getUTCFullYear()) : MONTHS_SHORT[d.getUTCMonth()];
  };
  parts.push(axis({ scale: xs, orient: "bottom", at: top + h, grid: [top, top + h], ticks, format: fmtX, title: L.x, size: fs }));
  parts.push(axis({ scale: ys, orient: "left", at: left, grid: [left, w - right], ticks: [0, 25, 50, 75, 100], format: (v) => `${v}%`, title: L.y, size: fs }));
  const obstacles: Box[] = [];
  const reqs: LabelRequest[] = [];

  // Launch marks; their labels are placed last, anywhere along the mark.
  const launches = [[REFERENCE.arc2Launch, L.launch2, C.c2], [REFERENCE.arc3Launch, L.launch3, C.c3]] as const;
  for (const [iso, , col] of launches) {
    const lx = xs(dayNum(iso));
    parts.push(el("line", { x1: lx, x2: lx, y1: top, y2: top + h, stroke: col, "stroke-width": 1, "stroke-dasharray": "2 3", "stroke-opacity": 0.8 }));
  }

  // Human references, from each ARC benchmark's launch.
  for (const [iso, v, col, lab, f] of [[REFERENCE.arc2Launch, REFERENCE.arc2HumanAverage, C.c2, L.humanAvg, "arc2"], [REFERENCE.arc3Launch, REFERENCE.arc3Human, C.c3, L.humanAll, "arc3"]] as const) {
    const hx = xs(dayNum(iso)), hy = ys(v);
    parts.push(el("line", { x1: hx, x2: xs(END), y1: hy, y2: hy, stroke: col, "stroke-width": f === focus ? 2 : 1.25, "stroke-dasharray": "1 3", "stroke-linecap": "round" }));
    if (f !== focus) continue;
    obstacles.push(...lineObstacles([[hx, hy], [xs(END), hy]], 8, 1));
    reqs.push({ x: hx + 4, y: hy, text: tpl(lab, { v: `${v}%` }), size: fs, sides: ["below-right", "above-right", "below-left", "above-left"], gap: 6, priority: 3, attrs: { class: "fig-t-halo fig-t-muted" } });
  }

  // Every entry of the focused benchmark.
  for (const s of SERIES) {
    if (s.focus !== focus) continue;
    for (const e of s.entries) {
      parts.push(el("circle", { cx: xs(e.x), cy: ys(e.score), r: narrow ? 2.2 : 2.6, fill: s.dash ? C.paper : s.color, stroke: s.dash ? s.color : undefined, "stroke-width": s.dash ? 1 : undefined, "fill-opacity": s.dash ? 1 : 0.35 }));
    }
  }

  // Best-to-date step lines, the focused benchmark on top.
  const order = [...SERIES].sort((a, b) => Number(a.focus === focus) - Number(b.focus === focus));
  for (const s of order) {
    const on = s.focus === focus;
    const pts: Array<[number, number]> = [];
    s.steps.forEach((p, i) => {
      const px = xs(p.x), py = ys(p.score);
      if (i > 0) pts.push([px, pts[pts.length - 1][1]]);
      pts.push([px, py]);
    });
    pts.push([xs(END), pts[pts.length - 1][1]]);
    const d = pts.map(([px, py], i) => `${i ? "L" : "M"}${px.toFixed(1)},${py.toFixed(1)}`).join("");
    parts.push(el("path", { d, fill: "none", stroke: s.color, "stroke-width": on ? 2.75 : 1.75, "stroke-opacity": on ? 1 : 0.55, "stroke-dasharray": s.dash, "stroke-linejoin": "round" }));
    for (const p of s.steps) parts.push(el("circle", { cx: xs(p.x), cy: ys(p.score), r: on ? 3.5 : 2.5, fill: s.color, "fill-opacity": on ? 1 : 0.55 }));
    // Only the focused lines keep labels off; the others are faded and the
    // labels carry a halo.
    if (on) obstacles.push(...lineObstacles(pts, 6, 2));
  }

  // Other protocols under the same name, at the snapshot.
  for (const [v, col, lab, f] of [[REFERENCE.arc2Private.score, C.c2, L.private, "arc2"], [REFERENCE.hleWithTools.score, C.c1, L.tools, "hle"]] as const) {
    const px = xs(END), py = ys(v);
    parts.push(el("path", { d: diamond(px, py, 6), fill: C.paper, stroke: col, "stroke-width": f === focus ? 2.25 : 1.5 }));
    obstacles.push({ x0: px - 7, y0: py - 7, x1: px + 7, y1: py + 7 });
    reqs.push({ x: px, y: py, text: tpl(lab, { v: `${fixed(v, 1)}%` }), size: fs, sides: ["left", "above-left", "below-left"], gap: 10, priority: f === focus ? 4 : 2, attrs: { class: `fig-t-halo${f === focus ? " fig-t-strong" : " fig-t-muted"}` } });
  }

  const pl = placeLabels(reqs, { x0: left + 2, y0: top - 2, x1: w - right, y1: top + h - 2 }, obstacles);
  parts.push(drawLabels(pl.placed));
  {
    const taken = [...obstacles, ...pl.placed.map((q) => q.box)];
    for (const [iso, lab] of launches) {
      const lx = xs(dayNum(iso));
      search: for (let k = 0; k < 12; k++) {
        const ty = top + 14 + k * 18;
        for (const [tx, anchor] of [[lx + 5, "start"], [lx - 5, "end"]] as const) {
          const box = textBox(tx, ty, lab, fs, anchor);
          if (box.x0 < left + 2 || box.x1 > w - right || box.y1 > top + h - 2) continue;
          if (taken.some((b) => overlaps(b, box))) continue;
          parts.push(text(tx, ty, lab, { "font-size": fs, "text-anchor": anchor, class: "fig-t-halo fig-t-muted" }));
          taken.push(box);
          break search;
        }
      }
    }
  }

  // ---- readout for the focused benchmark
  y = top + h + axisHeight(true, fs) + 16;
  const rp: string[] = [];
  const text1 = readout(focus, lang);
  for (const ln of lang === "zh" ? wrapCjk(text1, fs, w) : wrap(text1, fs, w)) { rp.push(text(0, y, ln, { "font-size": fs })); y += 17; }
  parts.push(g({ class: "fig-readout" }, ...rp));
  return svg(w, y, describe(st, lang), ...parts);
}

export default defineFigure({
  name: "benchmark-headroom",
  title: { en: labels.en.title, zh: labels.zh.title },
  labels,
  params: {
    focus: {
      kind: "choice", label: { en: "Show every entry of", zh: "逐条显示的基准" }, default: "arc2",
      options: [
        { value: "hle", label: { en: "HLE", zh: "HLE" } },
        { value: "arc2", label: { en: "ARC-AGI-2", zh: "ARC-AGI-2" } },
        { value: "arc3", label: { en: "ARC-AGI-3", zh: "ARC-AGI-3" } },
      ],
    },
  },
  render,
  describe,
});
